-- OPE-1233 / OPE-1187 COMPENSATING SQL. Ships with drizzle/0344 per OPE-53.
-- Restores the exact pre-change state: re-insert every retired series row with
-- ALL its columns, restore the Big E keeper's slug, point each event back at
-- its original series, then drop the redirect rows this migration added.
-- Order: parents first, or the FK would set the events' series_id NULL again.
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('093a7e65db7e106b000968d57759aaac', 'the-big-e-2026-eastern-states-exposition', 'The Big E 2026 (Eastern States Exposition)', 'a00e9108-9a86-4a64-acee-7dfe13f81f57', 'b4401fb2-8bb7-4764-80be-5625434f8cdc', NULL, 'The Big E (Eastern States Exposition) returns September 18 through October 4, 2026 in West Springfield, Massachusetts — New England''s largest agricultural fair and one of the top fairs in the country. The 17-day fair features the iconic Avenue of States with full-size replica state houses for all six New England states, big-name concert headliners on the Court of Honor stage, the Mardi Gras Parade, the New England Center, the Better Living Center, livestock and horse competitions, a sprawling midway, and hundreds of fair-food vendors including the famous cream puff and Big E baked potato. Attendance regularly exceeds 1.5 million visitors. Held at the Eastern States Exposition fairgrounds at 1305 Memorial Avenue, West Springfield, MA.', 'https://cdn.meetmeatthefair.com/events/beb08722-6476-43ea-9902-227099d6b23f/image-1778119097980.png', '["Fair"]', '["imported","mafa.org"]', 'PUBLIC', 'OPEN', 1782133213, 1782133213);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('0b109932bd58434bb450cea5bffcf536', 'wolcott-country-fair-ct', 'Wolcott Country Fair', 'bbcafbcc-6b45-4665-a5a3-ab7f4b03001a', 'd2f8daba-ec69-4db5-b1d8-e4c48b415691', NULL, 'Begun in 1979, the Wolcott Country Fair is the area''s largest agricultural and family fun event of the summer, attracting more than 30,000 people during the annual three-day event. Includes live entertainment, carnival rides, contests, pig racing, a petting zoo, concerts, and fireworks.', NULL, '["Fair","Agricultural Fair"]', '["CT","agricultural","country-fair","carnival-rides","family-friendly","summer","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('4c88ad7f5d3ee0d9288092322c6c08c4', 'bolton-fair-ma', 'Bolton Fair', '3545e9f7-6642-44c6-9d96-9e5668a2e544', 'c5e7c2f9-a212-4214-bd7c-a99104293d98', NULL, 'The Bolton Fair on August 14-16, 2026, is one of central Massachusetts''s longest-running agricultural fairs, held at the Fairgrounds at Lancaster in Lancaster, MA. The fair features livestock and 4-H exhibits, a craft vendor hall, food vendors, a midway with rides and games, live entertainment, and traditional fair contests including ox pulls, horse pulls, and tractor pulls. Run by the Bolton Fair Association, the event has been a Worcester County summer tradition since 1874 and draws thousands of visitors across the three-day weekend.', 'https://cdn.meetmeatthefair.com/events/bd15d9d9-7096-42da-b047-f2d3a8143950/image-1778119060783.png', '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('5baca53e750954425814280bcecf712e', 'tunbridge-worlds-fair-vt', 'Tunbridge World''s Fair', '65be445f-8e90-4d8b-b448-19b8c921c5dc', '2c706edc-0083-453d-9e62-ff5b4fcc66bc', NULL, 'The 2026 Tunbridge World''s Fair runs Sep 17–20 in Tunbridge, VT — held since 1867, one of Vermont''s most beloved agricultural fairs. Four days of working antique displays, horse and ox pulls, cattle shows, junior exhibits, and contra dancing.', 'https://cdn.meetmeatthefair.com/events/216065e4-88c0-47c2-827a-a9ef65958883/image-1778119175010.png', '["Fair"]', '["agricultural-fair","vermont","tunbridge","contra-dancing","heritage","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('61f62aeb84099cf81fd29bdbbb538766', 'belchertown-fair-ma', 'Belchertown Fair', 'cd343d94-fedf-4ede-a459-47488ecb592a', '5f5c7f50-8b32-4886-8f7a-7ded2ad93584', NULL, NULL, 'https://cdn.meetmeatthefair.com/events/f6652354-cb23-4026-a6e9-adbf9266d56e/image-1778119104292.png', '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('6291a61d6ba2d6fe74c455fe42502ef3', 'marshfield-fair-ma', 'Marshfield Fair', '7cb14b40-15d0-42f1-a7e6-066bcaf8df84', 'b471b92a-e5a0-4f5c-9213-bb325d5353a0', NULL, 'The 2026 Marshfield Fair runs Aug 21–30 at the Marshfield Fairgrounds in Marshfield, MA — Massachusetts''s largest 10-day agricultural fair on the South Shore, with livestock, horse shows, demolition derby, midway rides, fair food, craft vendors, live music, and family entertainment.', 'https://cdn.meetmeatthefair.com/events/e4c60af5-68ff-4f31-9d37-4bd62b55c51e/image-1778119071372.jpg', '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('8245349249691df00264699bfeded13b', 'haddam-neck-fair-ct', 'Haddam Neck Fair', 'b3aa78db-e11c-4cc9-87b5-862713b30020', '56506abc-45e1-4cd5-bea2-9d28de19073b', NULL, 'The Haddam Neck Fair is one of Connecticut''s major agricultural fairs, held every Labor Day weekend (Friday through Monday) at the Haddam Neck Fairgrounds. Features tractor and truck pulls, horse and oxen pulling contests, a horse show, livestock exhibits, food vendors, handmade crafts, and a family-friendly midway.', 'https://cdn.meetmeatthefair.com/events/04b19943-90ae-4748-87e7-854eb892aa61/og-1779734162834.png', '["Fair","Agricultural Fair"]', '["connecticut","agricultural","labor-day","livestock","crafts","annual","fall","family-friendly","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('95146e16b63fab1771440e3f344c833d', 'westfield-fair-ma', 'Westfield Fair', 'f6bf1c70-6dd3-4f19-9103-9a41e9cea53c', 'd0f3bd4d-89ff-4525-9f85-8a0e98d44179', NULL, NULL, NULL, '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('b494eab2ef15c2346f981870cf5586b1', 'barnstable-county-fair-ma', 'Barnstable County Fair', 'dd9201bd-b2ac-4adc-910d-3ef4aef68c02', 'd576c969-8d92-4e8d-9ce5-96094fa10701', NULL, 'The 2026 Barnstable County Fair runs Jul 20–25 at the Cape Cod Fairgrounds (1220 Nathan Ellis Hwy, East Falmouth, MA) — six-day Cape Cod agricultural fair with livestock, midway rides, fair food, demolition derby, monster trucks, live music, and family entertainment.', 'https://cdn.meetmeatthefair.com/events/f54221f5-16b4-472e-b14c-aeb752c8d916/image-1778119057228.png', '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('b84af3ad714af7a8cec5e9626b3d9e9f', 'woodstock-fair-ct', 'Woodstock Fair', 'f1d9b747-8a03-49bf-a252-5f1ba6161031', 'b7a4d4b4-5a68-41e5-8295-631d6edc74de', NULL, 'The 2026 Woodstock Fair runs Sep 3–7 at the Woodstock Fairgrounds in South Woodstock, CT — Connecticut''s second-oldest agricultural fair, 5 days over Labor Day weekend with livestock, horse pulls, tractor pulls, crafts, demolition derby, and carnival rides.', NULL, '["Fair","Agricultural Fair"]', '["connecticut","agricultural","labor-day","livestock","crafts","annual","fall","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('d037dcca2bba4b2d8b1b925a8ca27107', 'berlin-fair-ct', 'Berlin Fair', '2580bb02-02f2-4c58-98b1-f6368049536e', '06606531-165a-4588-8b65-5aba158b3fb1', NULL, 'The 2026 Berlin Fair runs Sep 17–20 at the Berlin Fairgrounds in Berlin, CT — four-day agricultural fair with livestock exhibitions, handmade crafts, food concessions, midway rides, tractor pulls, and family entertainment.', NULL, '["Fair","Agricultural Fair"]', '["connecticut","agricultural","livestock","crafts","annual","fall","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('d9c88d9fd9778e8fb1d398bc64083528', 'sterling-fair-ma', 'Sterling Fair', '047962de-3073-454c-bfc2-2edb0a4958d7', 'cef95549-0648-4ec6-af68-7fe8f4c041ee', NULL, NULL, NULL, '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
INSERT OR IGNORE INTO event_series (id, canonical_slug, name, venue_id, promoter_id, recurrence_rule, description, image_url, categories, tags, primary_audience, public_access, created_at, updated_at) VALUES ('f565175e13121c267f3e1ceb81187769', 'cummington-fair-ma', 'Cummington Fair', '733dbdc7-2f87-4bf6-8bf9-9f060440a890', '11eeddf0-aee6-430f-8ac7-bf968c732a91', NULL, 'The Cummington Fair on August 27-30, 2026, is a four-day agricultural fair in the western Massachusetts hilltowns, held at the historic Cummington Fairgrounds. Founded in 1883 and run by the Hillside Agricultural Society, the fair features livestock and agricultural exhibits, horse pulls, ox pulls, vintage tractor displays, a midway with rides, food vendors, craft vendors, live entertainment, and traditional country fair competitions. It is the largest annual gathering in the Hampshire County hilltowns.', 'https://cdn.meetmeatthefair.com/events/caa6881f-cba5-4576-83af-1f68f2a1d841/image-1778119078042.png', '["Fair"]', '["imported","mafa.org","dates-pending-official"]', 'PUBLIC', 'OPEN', 1782133213, 1784127161);
