UPDATE event_series SET description = 'The Big E (Eastern States Exposition) returns September 18 through October 4, 2026 in West Springfield, Massachusetts — New England''s largest agricultural fair and one of the top fairs in the country. The 17-day fair features the iconic Avenue of States with full-size replica state houses for all six New England states, big-name concert headliners on the Court of Honor stage, the Mardi Gras Parade, the New England Center, the Better Living Center, livestock and horse competitions, a sprawling midway, and hundreds of fair-food vendors including the famous cream puff and Big E baked potato. Attendance regularly exceeds 1.5 million visitors. Held at the Eastern States Exposition fairgrounds at 1305 Memorial Avenue, West Springfield, MA.' WHERE id = '415479ad80a361d18839c69ee5d998dd';
